 "SELECT f.AMOUNTLINKEDINBPM, " +
 " s.AMOUNTINCURRENTREQ, " +
 " s.AMOUNTINREQCURRENCY " +
 "FROM ODC_FCTRANSACTION f " +
 "JOIN ODC_SELECTEDTRANSACTIONS s ON f.ID = s.TRANSACTIONID " +
 "JOIN ( " +
 " SELECT TRANSACTIONID, MAX(ID) AS max_id " +
 " FROM ODC_SELECTEDTRANSACTIONS " +
 " WHERE REQUESTID = ? " +
 " AND (ISDELETED IS NULL OR ISDELETED <> 'Yes') " +
 " GROUP BY TRANSACTIONID " +
 ") latest ON s.TRANSACTIONID = latest.TRANSACTIONID AND s.ID = latest.max_id " +
 "WHERE s.REQUESTID = ? " +
 " AND (s.ISDELETED IS NULL OR s.ISDELETED <> 'Yes')";


