    tw.local.transactionsWithID[i].referenceNumber = item.referenceNumber;
    tw.local.transactionsWithID[i].postingDate = new Date(item.postingDate);
    tw.local.transactionsWithID[i].valueDate = new Date(item.valueDate);
    tw.local.transactionsWithID[i].transactionAmount = item.transactionAmount;
    tw.local.transactionsWithID[i].existAmount = item.existAmount;
