    tw.local.transactionsWithID[i].amountAllocatedForCurrencyRequest = item.amountAllocatedForCurrencyRequest;
    tw.local.transactionsWithID[i].allocatedAmountInRequestCurrency = item.allocatedAmountInRequestCurrency;
    tw.local.transactionsWithID[i].requestID = item.requestID;
    tw.local.transactionsWithID[i].remove = item.remove;
}

