TWComponent.script:
tw.local.sqlStatements = new tw.object.listOf.SQLStatement();

for (var i = 0; i < tw.local.transactions.listLength; i++) {
    var sqlStatement = new tw.object.SQLStatement();

    sqlStatement.sql =
  "SELECT f.AMOUNTLINKEDINBPM, " +
  "       s.AMOUNTINCURRENTREQ, " +
  "       s.AMOUNTINREQCURRENCY " +
  "FROM ODC_FCTRANSACTION f " +
  "JOIN ODC_SELECTEDTRANSACTIONS s ON f.ID = s.TRANSACTIONID " +
  "JOIN ( " +
  "    SELECT TRANSACTIONID, MAX(ID) AS max_id " +
  "    FROM ODC_SELECTEDTRANSACTIONS " +
  "    WHERE REQUESTID = ? " +
  "      AND (ISDELETED IS NULL OR ISDELETED <> 'Yes') " +
  "    GROUP BY TRANSACTIONID " +
  ") latest ON s.TRANSACTIONID = latest.TRANSACTIONID AND s.ID = latest.max_id " +
  "WHERE s.REQUESTID = ? " +
  "  AND (s.ISDELETED IS NULL OR s.ISDELETED <> 'Yes')";


    sqlStatement.parameters = new tw.object.listOf.SQLParameter();

    var param1 = new tw.object.SQLParameter();
    param1.value = tw.local.transactions[i].requestID;
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, param1);

    var param2 = new tw.object.SQLParameter();
    param2.value =tw.local.transactions[i].requestID;
    sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, param2);

    tw.local.sqlStatements.insertIntoList(tw.local.sqlStatements.listLength, sqlStatement);
}

tw.local.sqlStatements = new tw.object.listOf.SQLStatement();

for (var i = 0; i < tw.local.transactions.listLength; i++) {

	var sqlStatement = new tw.object.SQLStatement();

	sqlStatement.sql = "SELECT AMOUNTINCURRENTREQ, AMOUNTINREQCURRENCY, TRANSACTIONID " + "FROM " + tw.env.LKP_DB_Schema + ".ODC_SELECTEDTRANSACTIONS " + "WHERE ID = (SELECT MAX(ID) FROM " + tw.env.DBSchema + ".ODC_SELECTEDTRANSACTIONS WHERE REQUESTID = ? AND (isDeleted <> 'Yes' OR isDeleted IS NULL) AND TRANSACTIONID = ? )";

	sqlStatement.parameters = new tw.object.listOf.SQLParameter();

	var param1 = new tw.object.SQLParameter();
	param1.value = tw.local.transactions[i].requestID;
	sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, param1);

	var param2 = new tw.object.SQLParameter();
	param2.value = tw.local.transactionID[i];
	sqlStatement.parameters.insertIntoList(sqlStatement.parameters.listLength, param2);

	tw.local.sqlStatements.insertIntoList(tw.local.sqlStatements.listLength, sqlStatement);
}

processPrePosts.script:
tw.local.transactionID = [];
tw.local.transIDs = [];
if (tw.local.sqlResults.listLength > 0) {
    for (var i = 0; i < tw.local.sqlResults.listLength; i++) {
        var result = tw.local.sqlResults[i];
        if (result.rows.listLength > 0 && result.rows[0].data) {

            tw.local.transactions[i].existAmount = result.rows[0].data[1];
//		  tw.local.transIDs.insertIntoList(tw.local.transIDs.listLength, i);
		 tw.local.transactionsWithID[i].transID = result.rows[0].data[0];
            tw.local.transactionID.insertIntoList(tw.local.transactionID.listLength, result.rows[0].data[0]);
        }
    }
}

tw.local.results = JSON.stringify(tw.local.transactions);

