    var item = parsedData.items[i];
    tw.local.transactions[i] = new tw.object.FCTransactions();
    tw.local.transactions[i].accountNo = item.accountNo;
    tw.local.transactions[i].referenceNumber = item.referenceNumber;
    tw.local.transactions[i].postingDate = new Date(item.postingDate);
    tw.local.transactions[i].valueDate = new Date(item.valueDate);
    tw.local.transactions[i].transactionAmount = item.transactionAmount;
    tw.local.transactions[i].existAmount = item.existAmount;
    tw.local.transactions[i].currency = item.currency;
    tw.local.transactions[i].amountAllocatedForCurrencyRequest = item.amountAllocatedForCurrencyRequest;
    tw.local.transactions[i].allocatedAmountInRequestCurrency = item.allocatedAmountInRequestCurrency;
    tw.local.transactions[i].requestID = item.requestID;
    tw.local.transactions[i].remove = item.remove;
}

log.info("tw.local.transactions after mapping: " + JSON.stringify(tw.local.transactions));

